1	<script lang="ts">
2	  import { onDestroy, onMount, untrack } from 'svelte';
3	
4	  import {
5	    apiFetch,
6	    downloadExport,
7	    fetchAudioObjectUrl,
8	    type AudioKind,
9	  } from '../api';
10	  import { shouldApplyAudioResult } from '../audioLoad';
11	  import TabPlayer from '../components/TabPlayer.svelte';
12	  import {
13	    defaultScorePart,
14	    listenForPart,
15	    parseScoreParts,
16	    partLabel,
17	    showPartSwitcher,
18	    type ScorePart,
19	  } from '../scoreParts';
20	
21	  type ScoreLayout = {
22	    measure_sec: number;
23	    measure_width: number;
24	    row_height: number;
25	    bars_per_line: number;
26	    measure_count: number;
27	    row_count: number;
28	    origin_x: number;
29	    origin_y: number;
30	    note_inset: number;
31	    note_span: number;
32	    width: number;
33	    height: number;
34	  };
35	
36	  type Score = {
37	    view: string;
38	    svg: string;
39	    text: string;
40	    meta: {
41	      title: string;
42	      key: string;
43	      tempo_bpm: number;
44	      duration_sec: number;
45	      beats_per_measure?: number;
46	      tuning_name: string;
47	      capo: number;
48	      transpose: number;
49	      bars_per_line: number;
50	      lyrics_status?: string;
51	    };
52	    layout?: ScoreLayout | null;
53	    artifacts: Record<string, boolean>;
54	    part?: string;
55	    parts?: string[];
56	  };
57	
58	  type RunMeta = {
59	    details?: {
60	      lead_rhythm_fallback?: boolean;
61	      lead_rhythm_fallback_reason?: string;
62	    } | null;
63	  };
64	
65	  let {
66	    runId,
67	    onnew,
68	  }: {
69	    runId: string;
70	    onnew: () => void;
71	  } = $props();
72	
73	  let view = $state('staff');
74	  let tuning = $state('Standard (EADGBE)');
75	  let capo = $state(0);
76	  let transpose = $state(0);
77	  let bars = $state(4);
78	  let score = $state<Score | null>(null);
79	  let error = $state<string | null>(null);
80	  let part = $state<ScorePart>('lead');
81	  let parts = $state<ScorePart[]>(['combined']);
82	  let listen = $state<AudioKind>('original');
83	  let audioSrc = $state<string | null>(null);
84	  let audioPending = $state(false);
85	  let confirmNew = $state(false);
86	  let exportOpen = $state(false);
87	  let panelOpen = $state(false);
88	  let fallbackNotice = $state<string | null>(null);
89	  let didInitialListenSync = false;
90	
91	  let audioEl = $state<HTMLAudioElement | null>(null);
92	  let scoreEl = $state<HTMLDivElement | null>(null);
93	  let playing = $state(false);
94	  let playTime = $state(0);
95	  let audioDuration = $state(0);
96	  // Non-reactive generation counter so $effect does not re-subscribe on bumps.
97	  let audioLoadGen = 0;
98	
99	  async function loadRunMeta() {
100	    try {
101	      const meta = await apiFetch<RunMeta>(`/api/runs/${encodeURIComponent(runId)}`);
102	      if (meta.details?.lead_rhythm_fallback) {
103	        fallbackNotice =
104	          meta.details.lead_rhythm_fallback_reason ||
105	          'Lead/rhythm split was unavailable; showing a single guitar tab.';
106	      } else {
107	        fallbackNotice = null;
108	      }
109	    } catch {
110	      fallbackNotice = null;
111	    }
112	  }
113	
114	  async function loadScore() {
115	    try {
116	      const q = new URLSearchParams({
117	        view,
118	        tuning,
119	        capo: String(capo),
120	        transpose: String(transpose),
121	        bars: String(bars),
122	        part,
123	      });
124	      const next = await apiFetch<Score>(`/api/runs/${encodeURIComponent(runId)}/score?${q}`);
125	      score = next;
126	      const parsed = parseScoreParts(next.parts);
127	      parts = parsed;
128	      if (next.part === 'lead' || next.part === 'rhythm' || next.part === 'combined') {
129	        part = next.part;
130	      } else {
131	        part = defaultScorePart(parsed);
132	      }
133	      if (!didInitialListenSync) {
134	        listen = listenForPart(part, next.artifacts);
135	        didInitialListenSync = true;
136	      }
137	      error = null;
138	    } catch (err) {
139	      error = err instanceof Error ? err.message : 'Could not load score.';
140	    }
141	  }
142	
143	  function selectPart(next: ScorePart) {
144	    if (next === part) return;
145	    part = next;
146	    listen = listenForPart(next, score?.artifacts);
147	  }
148	
149	  async function loadAudio(kind: AudioKind) {
150	    // untrack: reading/writing audioSrc must not re-subscribe the listen effect
151	    // (that loop nulls the blob forever and storms /audio with 200s).
152	    const prev = untrack(() => audioSrc);
153	    if (prev) URL.revokeObjectURL(prev);
154	    audioLoadGen += 1;
155	    const gen = audioLoadGen;
156	    untrack(() => {
157	      audioSrc = null;
158	      audioPending = true;
159	    });
160	    try {
161	      const url = await fetchAudioObjectUrl(runId, kind);
162	      if (!shouldApplyAudioResult(gen, audioLoadGen)) {
163	        URL.revokeObjectURL(url);
164	        return;
165	      }
166	      untrack(() => {
167	        audioSrc = url;
168	        audioPending = false;
169	      });
170	    } catch {
171	      if (!shouldApplyAudioResult(gen, audioLoadGen)) return;
172	      untrack(() => {
173	        audioSrc = null;
174	        audioPending = false;
175	      });
176	    }
177	  }
178	
179	  onMount(() => {
180	    void loadRunMeta();
181	    void loadScore();
182	  });
183	
184	  onDestroy(() => {
185	    audioLoadGen += 1;
186	    const prev = untrack(() => audioSrc);
187	    if (prev) URL.revokeObjectURL(prev);
188	  });
189	
190	  $effect(() => {
191	    void view;
192	    void tuning;
193	    void capo;
194	    void transpose;
195	    void bars;
196	    void part;
197	    void loadScore();
198	  });
199	
200	  // Depends only on listen (+ runId from props). loadAudio uses untrack for audioSrc.
201	  $effect(() => {
202	    const kind = listen;
203	    void runId;
204	    playing = false;
205	    playTime = 0;
206	    audioDuration = 0;
207	    void loadAudio(kind);
208	  });
209	
210	  function togglePlay() {
211	    if (!audioEl || !audioSrc) return;
212	    if (audioEl.paused) void audioEl.play();
213	    else audioEl.pause();
214	  }
215	
216	  function seekTo(time: number) {
217	    if (!audioEl) return;
218	    audioEl.currentTime = time;
219	    playTime = time;
220	  }
221	
222	  // Percentage position of the playhead within the SVG box. The SVG scales
223	  // uniformly (width:100%, height:auto), so percentages track it exactly as
224	  // long as the generator keeps that scaling; if it ever changes, switch to
225	  // getScreenCTM() math.
226	  let playhead = $derived.by(() => {
227	    const layout = score?.layout;
228	    if (view !== 'staff' || !layout || !audioEl) return null;
229	    const measureSec = layout.measure_sec > 0 ? layout.measure_sec : 1;
230	    const barsPerLine = Math.max(1, layout.bars_per_line);
231	    let measureIndex = Math.floor(playTime / measureSec);
232	    measureIndex = Math.max(0, Math.min(layout.measure_count - 1, measureIndex));
233	    const row = Math.floor(measureIndex / barsPerLine);
234	    const col = measureIndex % barsPerLine;
235	    const rel = Math.max(0, Math.min(1, (playTime - measureIndex * measureSec) / measureSec));
236	    const x = layout.origin_x + col * layout.measure_width + layout.note_inset + rel * layout.note_span;
237	    const top = layout.origin_y + row * layout.row_height;
238	    // Cover the six staff lines (5 × 12px span) plus a small margin, like the
239	    // row markers in notation_view.score_playhead_html.
240	    const blockH = Math.min(64, layout.height - top);
241	    return {
242	      left: `${(x / layout.width) * 100}%`,
243	      top: `${(top / layout.height) * 100}%`,
244	      height: `${(blockH / layout.height) * 100}%`,
245	    };
246	  });
247	
248	  $effect(() => {
249	    if (!playing) return;
250	    let raf = 0;
251	    const tick = () => {
252	      playTime = audioEl?.currentTime ?? 0;
253	      raf = requestAnimationFrame(tick);
254	    };
255	    raf = requestAnimationFrame(tick);
256	    return () => cancelAnimationFrame(raf);
257	  });
258	
259	  // Keep the active staff row in view while playing so the tab moves with the song.
260	  let followedRow = -1;
261	  $effect(() => {
262	    if (!playing) {
263	      followedRow = -1;
264	      return;
265	    }
266	    const layout = score?.layout;
267	    if (!layout || !scoreEl || view !== 'staff') return;
268	    const measureSec = layout.measure_sec > 0 ? layout.measure_sec : 1;
269	    const barsPerLine = Math.max(1, layout.bars_per_line);
270	    const measureIndex = Math.max(
271	      0,
272	      Math.min(layout.measure_count - 1, Math.floor(playTime / measureSec)),
273	    );
274	    const row = Math.floor(measureIndex / barsPerLine);
275	    if (row === followedRow) return;
276	    followedRow = row;
277	    const reduce =
278	      typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches;
279	    scoreEl
280	      .querySelector('.playhead')
281	      ?.scrollIntoView({ block: 'nearest', behavior: reduce ? 'auto' : 'smooth' });
282	  });
283	
284	  $effect(() => {
285	    const onKey = (ev: KeyboardEvent) => {
286	      if (ev.code !== 'Space') return;
287	      const target = ev.target as HTMLElement | null;
288	      if (target && ['INPUT', 'SELECT', 'TEXTAREA', 'BUTTON'].includes(target.tagName)) return;
289	      if (exportOpen || confirmNew || !audioSrc) return;
290	      ev.preventDefault();
291	      togglePlay();
292	    };
293	    window.addEventListener('keydown', onKey);
294	    return () => window.removeEventListener('keydown', onKey);
295	  });
296	
297	  function onScoreClick(ev: MouseEvent) {
298	    const layout = score?.layout;
299	    if (view !== 'staff' || !layout || !audioEl || !scoreEl) return;
300	    if ((ev.target as HTMLElement).closest('.float')) return;
301	    const svg = scoreEl.querySelector('svg');
302	    if (!svg) return;
303	    const rect = svg.getBoundingClientRect();
304	    const scaleX = rect.width / layout.width;
305	    const scaleY = rect.height / layout.height;
306	    if (scaleX <= 0 || scaleY <= 0) return;
307	    const x = (ev.clientX - rect.left) / scaleX;
308	    const y = (ev.clientY - rect.top) / scaleY;
309	    const barsPerLine = Math.max(1, layout.bars_per_line);
310	    const measureSec = layout.measure_sec > 0 ? layout.measure_sec : 1;
311	    const row = Math.max(
312	      0,
313	      Math.min(layout.row_count - 1, Math.floor((y - layout.origin_y) / layout.row_height)),
314	    );
315	    const col = Math.max(
316	      0,
317	      Math.min(barsPerLine - 1, Math.floor((x - layout.origin_x) / layout.measure_width)),
318	    );
319	    const rel = Math.max(
320	      0,
321	      Math.min(
322	        1,
323	        (x - layout.origin_x - col * layout.measure_width - layout.note_inset) / layout.note_span,
324	      ),
325	    );
326	    seekTo((row * barsPerLine + col + rel) * measureSec);
327	  }
328	
329	  async function sendFeedback(answer: 'yes' | 'no') {
330	    await apiFetch(`/api/runs/${encodeURIComponent(runId)}/feedback`, {
331	      method: 'POST',
332	      headers: { 'Content-Type': 'application/json' },
333	      body: JSON.stringify({ answer }),
334	    });
335	  }
336	
337	  async function doExport(format: string) {
338	    await downloadExport(runId, { format, tuning, capo, transpose, bars });
339	    exportOpen = false;
340	  }
341	</script>
342	
343	<section class="result rise-in">
344	  {#if error}
345	    <p class="banner" role="alert">{error}</p>
346	  {/if}
347	  {#if fallbackNotice}
348	    <p class="banner warn" role="status">{fallbackNotice}</p>
349	  {/if}
350	
351	  <header class="chrome">
352	    <div class="identity">
353	      <h1>{score?.meta.title || 'Result'}</h1>
354	      {#if score}
355	        <p class="meta">
356	          Key {score.meta.key} · {Math.round(score.meta.tempo_bpm)} BPM ·
357	          {Math.floor(score.meta.duration_sec / 60)}:{String(Math.floor(score.meta.duration_sec % 60)).padStart(2, '0')}
358	        </p>
359	      {/if}
360	    </div>
361	    <div class="views" role="tablist" aria-label="Score view">
362	      {#each [['staff', 'Tab'], ['chords', 'Chords'], ['piano', 'Piano roll'], ['text', 'Text']] as [id, label]}
363	        <button
364	          type="button"
365	          class:active={view === id}
366	          onclick={() => (view = id)}>{label}</button
367	        >
368	      {/each}
369	    </div>
370	  </header>
371	
372	  {#if showPartSwitcher(parts)}
373	    <div class="parts" role="tablist" aria-label="Guitar part">
374	      {#each parts as id}
375	        <button
376	          type="button"
377	          class:active={part === id}
378	          onclick={() => selectPart(id)}>{partLabel(id)}</button
379	        >
380	      {/each}
381	    </div>
382	  {/if}
383	
384	  <div class="score-stage">
385	    <!-- Click-to-seek on the score surface; keyboard users get the same via the transport slider. -->
386	    <!-- svelte-ignore a11y_no_noninteractive_element_interactions, a11y_click_events_have_key_events -->
387	    <div class="score" role="img" aria-label="Score" bind:this={scoreEl} onclick={onScoreClick}>
388	      {#if score?.svg}
389	        {@html score.svg}
390	      {/if}
391	      {#if playhead}
392	        <div class="playhead-layer" aria-hidden="true">
393	          <div
394	            class="playhead"
395	            style:left={playhead.left}
396	            style:top={playhead.top}
397	            style:height={playhead.height}
398	          ></div>
399	        </div>
400	      {/if}
401	      {#if score?.text}
402	        <pre>{score.text}</pre>
403	      {/if}
404	      {#if !score}
405	        <p class="muted"><span class="spinner is-on"></span> Loading score…</p>
406	      {/if}
407	    </div>
408	
409	    <div class="float" class:open={panelOpen}>
410	      <button
411	        type="button"
412	        class="fab"
413	        aria-expanded={panelOpen}
414	        aria-controls="result-controls"
415	        onclick={() => (panelOpen = !panelOpen)}
416	      >
417	        {#if panelOpen}
418	          Close
419	        {:else}
420	          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
421	            <path
422	              d="M4 7h16M4 12h16M4 17h10"
423	              stroke="currentColor"
424	              stroke-width="2"
425	              stroke-linecap="round"
426	            />
427	          </svg>
428	          Controls
429	        {/if}
430	      </button>
431	
432	      {#if panelOpen}
433	        <div class="panel" id="result-controls" role="dialog" aria-label="Score controls">
434	          <div class="panel-actions">
435	            <div class="export">
436	              <button type="button" class="ghost" onclick={() => (exportOpen = !exportOpen)}
437	                >Export</button
438	              >
439	              {#if exportOpen}
440	                <div class="menu">
441	                  {#each ['pdf', 'midi', 'tab', 'gp5'] as fmt}
442	                    {#if !score || score.artifacts[fmt] !== false}
443	                      <button type="button" onclick={() => doExport(fmt)}>{fmt.toUpperCase()}</button>
444	                    {/if}
445	                  {/each}
446	                  {#if score?.artifacts.guitar_stem}
447	                    <button type="button" onclick={() => doExport('guitar_stem')}>Guitar stem</button>
448	                  {/if}
449	                  {#if score?.artifacts.musicxml}
450	                    <button type="button" onclick={() => doExport('musicxml')}>MusicXML</button>
451	                  {/if}
452	                </div>
453	              {/if}
454	            </div>
455	            {#if confirmNew}
456	              <span class="confirm">Start over?</span>
457	              <button type="button" class="ghost" onclick={() => (confirmNew = false)}>Keep</button>
458	              <button type="button" class="danger" onclick={onnew}>Discard</button>
459	            {:else}
460	              <button type="button" class="ghost" onclick={() => (confirmNew = true)}>New song</button>
461	            {/if}
462	          </div>
463	
464	          <h2>Inspector</h2>
465	          <label class="field"
466	            ><span>Tuning</span>
467	            <select bind:value={tuning}>
468	              <option>Standard (EADGBE)</option>
469	              <option>Drop D</option>
470	              <option>Half-step down</option>
471	            </select></label
472	          >
473	          <label class="field"
474	            ><span>Capo</span>
475	            <input type="number" min="0" max="12" bind:value={capo} /></label
476	          >
477	          <label class="field"
478	            ><span>Transpose</span>
479	            <input type="number" min="-12" max="12" bind:value={transpose} /></label
480	          >
481	          <label class="field"
482	            ><span>Bars per line</span>
483	            <input type="number" min="1" max="8" bind:value={bars} /></label
484	          >
485	
486	          <div class="feedback">
487	            <span>Does this sound right?</span>
488	            <button type="button" class="ghost" onclick={() => sendFeedback('yes')}>Yes</button>
489	            <button type="button" class="ghost" onclick={() => sendFeedback('no')}>Not quite</button>
490	          </div>
491	        </div>
492	      {/if}
493	    </div>
494	  </div>
495	
496	  <div class="transport">
497	    <fieldset class="listen">
498	      <legend>Listen</legend>
499	      <label><input type="radio" bind:group={listen} value="original" /> Original</label>
500	      {#if score?.artifacts.guitar_stem}
501	        <label><input type="radio" bind:group={listen} value="stem" /> Guitar stem</label>
502	      {/if}
503	      {#if score?.artifacts.lead_guitar}
504	        <label><input type="radio" bind:group={listen} value="lead" /> Lead</label>
505	      {/if}
506	      {#if score?.artifacts.rhythm_guitar}
507	        <label><input type="radio" bind:group={listen} value="rhythm" /> Rhythm</label>
508	      {/if}
509	    </fieldset>
510	    <audio
511	      bind:this={audioEl}
512	      src={audioSrc}
513	      preload="metadata"
514	      class="sr-audio"
515	      onplay={() => (playing = true)}
516	      onpause={() => (playing = false)}
517	      onended={() => (playing = false)}
518	      onloadedmetadata={() => (audioDuration = audioEl?.duration ?? 0)}
519	    ></audio>
520	    <TabPlayer
521	      available={audioSrc !== null}
522	      pending={audioPending}
523	      {playing}
524	      currentTime={playTime}
525	      duration={audioDuration}
526	      ontoggle={togglePlay}
527	      onseek={seekTo}
528	    />
529	  </div>
530	</section>
531	
532	<style>
533	  .result {
534	    display: flex;
535	    flex-direction: column;
536	    gap: var(--space-3);
537	    min-height: calc(100vh - 120px);
538	  }
539	  .chrome {
540	    display: flex;
541	    flex-direction: column;
542	    gap: var(--space-3);
543	    flex-shrink: 0;
544	  }
545	  .identity {
546	    display: flex;
547	    flex-wrap: wrap;
548	    align-items: baseline;
549	    gap: var(--space-3) var(--space-4);
550	  }
551	  h1 {
552	    font-family: var(--font-display);
553	    font-size: var(--fs-5);
554	    font-weight: var(--weight-medium);
555	  }
556	  .meta {
557	    color: var(--muted);
558	    font-family: var(--font-mono);
559	    font-size: var(--fs-2);
560	  }
561	  .views {
562	    display: flex;
563	    gap: var(--space-2);
564	    flex-wrap: wrap;
565	  }
566	  .views button {
567	    min-height: 44px;
568	    padding: 0 var(--space-3);
569	    border: 0;
570	    border-radius: var(--radius-1);
571	    background: transparent;
572	    color: var(--muted);
573	    cursor: pointer;
574	  }
575	  .views button.active {
576	    background: var(--accent);
577	    color: var(--accent-ink);
578	    font-weight: var(--weight-semibold);
579	  }
580	  .parts {
581	    display: flex;
582	    gap: var(--space-2);
583	    flex-wrap: wrap;
584	  }
585	  .parts button {
586	    min-height: 40px;
587	    padding: 0 var(--space-3);
588	    border: 1px solid rgba(168, 184, 204, 0.35);
589	    border-radius: var(--radius-1);
590	    background: transparent;
591	    color: var(--muted);
592	    cursor: pointer;
593	  }
594	  .parts button.active {
595	    border-color: var(--accent);
596	    background: color-mix(in srgb, var(--accent) 22%, transparent);
597	    color: var(--text);
598	    font-weight: var(--weight-semibold);
599	  }
600	  .score-stage {
601	    position: relative;
602	    flex: 1 1 auto;
603	    min-height: 0;
604	    display: flex;
605	    flex-direction: column;
606	  }
607	  .score {
608	    position: relative;
609	    flex: 1 1 auto;
610	    background: color-mix(in srgb, var(--art) 72%, var(--surface));
611	    border: 1px solid color-mix(in srgb, var(--line) 14%, transparent);
612	    border-radius: var(--radius-2);
613	    padding: var(--space-3);
614	    overflow-x: hidden;
615	    overflow-y: auto;
616	    min-height: calc(100vh - 280px);
617	  }
618	  .playhead-layer {
619	    position: absolute;
620	    top: var(--space-3);
621	    bottom: var(--space-3);
622	    left: var(--space-3);
623	    right: var(--space-3);
624	    pointer-events: none;
625	  }
626	  .playhead {
627	    position: absolute;
628	    width: 2px;
629	    background: var(--accent);
630	    border-radius: 1px;
631	    box-shadow: 0 0 6px color-mix(in srgb, var(--accent) 65%, transparent);
632	  }
633	  .score :global(svg) {
634	    display: block;
635	    width: 100%;
636	    max-width: 100%;
637	    height: auto;
638	  }
639	  pre {
640	    white-space: pre;
641	    font-family: var(--font-mono);
642	    font-size: var(--fs-3);
