2	  import { onDestroy, onMount } from 'svelte';
3	
4	  import { apiFetch } from '../api';
5	
6	  type JobSnap = {
7	    id: string;
8	    state: string;
9	    title: string;
10	    rows: { id: string; label: string; state: string; detail: string }[];
11	    message: string;
12	    fraction: number;
13	    run_id: string | null;
14	    error: { code: string; message: string; hint?: string } | null;
15	  };
16	
17	  let {
18	    jobId,
19	    ondone,
20	    onfail,
21	  }: {
22	    jobId: string;
23	    ondone: (runId: string) => void;
24	    onfail: (message: string) => void;
25	  } = $props();
26	
27	  let snap = $state<JobSnap | null>(null);
28	  let started = $state(Date.now());
29	  let elapsed = $state(0);
30	  let finished = false;
31	  let timer: ReturnType<typeof setInterval> | undefined;
32	  let poller: ReturnType<typeof setInterval> | undefined;
33	
34	  function stopPolling() {
35	    finished = true;
36	    if (timer) clearInterval(timer);
37	    if (poller) clearInterval(poller);
38	    timer = undefined;
39	    poller = undefined;
40	  }
41	
42	  async function poll() {
43	    if (finished) return;
44	    try {
45	      const next = await apiFetch<JobSnap>(`/api/jobs/${encodeURIComponent(jobId)}`);
46	      snap = next;
47	      if (next.state === 'done' && next.run_id) {
48	        stopPolling();
49	        ondone(next.run_id);
50	        return;
51	      }
52	      if (next.state === 'failed') {
53	        stopPolling();
54	        onfail(next.error?.message || next.message || 'Conversion failed.');
55	      }
56	    } catch (err) {
57	      stopPolling();
58	      onfail(err instanceof Error ? err.message : 'Lost connection to the job.');
59	    }
60	  }
61	
62	  onMount(() => {
63	    started = Date.now();
64	    timer = setInterval(() => {
65	      elapsed = Math.floor((Date.now() - started) / 1000);
66	    }, 500);
67	    void poll();
68	    poller = setInterval(() => void poll(), 500);
69	  });
70	
71	  onDestroy(() => {
72	    stopPolling();
73	  });
74	</script>
