9	  } from '../api';
10	  import { shouldApplyAudioResult } from '../audioLoad';
11	  import TabPlayer from '../components/TabPlayer.svelte';
12	  import {
13	    defaultScorePart,
14	    listenForPart,
15	    parseScoreParts,
16	    partLabel,
17	    showPartSwitcher,
18	    type ScorePart,
19	  } from '../scoreParts';
20	
21	  type ScoreLayout = {
22	    measure_sec: number;
23	    measure_width: number;
24	    row_height: number;
25	    bars_per_line: number;
26	    measure_count: number;
27	    row_count: number;
28	    origin_x: number;
29	    origin_y: number;
30	    note_inset: number;
31	    note_span: number;
32	    width: number;
33	    height: number;
34	  };
