36	  type Score = {
37	    view: string;
38	    svg: string;
39	    text: string;
40	    meta: {
41	      title: string;
42	      key: string;
43	      tempo_bpm: number;
44	      duration_sec: number;
45	      beats_per_measure?: number;
46	      tuning_name: string;
47	      capo: number;
48	      transpose: number;
49	      bars_per_line: number;
50	      lyrics_status?: string;
51	    };
