73	  let view = $state('staff');
74	  let tuning = $state('Standard (EADGBE)');
75	  let capo = $state(0);
76	  let transpose = $state(0);
77	  let bars = $state(4);
78	  let score = $state<Score | null>(null);
79	  let error = $state<string | null>(null);
80	  let part = $state<ScorePart>('lead');
81	  let parts = $state<ScorePart[]>(['combined']);
82	  let listen = $state<AudioKind>('original');
83	  let audioSrc = $state<string | null>(null);
84	  let audioPending = $state(false);
85	  let confirmNew = $state(false);
86	  let exportOpen = $state(false);
87	  let panelOpen = $state(false);
88	  let fallbackNotice = $state<string | null>(null);
89	  let didInitialListenSync = false;
90	
91	  let audioEl = $state<HTMLAudioElement | null>(null);
92	  let scoreEl = $state<HTMLDivElement | null>(null);
93	  let playing = $state(false);
94	  let playTime = $state(0);
