98	
99	  async function loadRunMeta() {
100	    try {
101	      const meta = await apiFetch<RunMeta>(`/api/runs/${encodeURIComponent(runId)}`);
102	      if (meta.details?.lead_rhythm_fallback) {
103	        fallbackNotice =
104	          meta.details.lead_rhythm_fallback_reason ||
105	          'Lead/rhythm split was unavailable; showing a single guitar tab.';
106	      } else {
107	        fallbackNotice = null;
108	      }
109	    } catch {
