116	      const q = new URLSearchParams({
117	        view,
118	        tuning,
119	        capo: String(capo),
120	        transpose: String(transpose),
121	        bars: String(bars),
122	        part,
123	      });
124	      const next = await apiFetch<Score>(`/api/runs/${encodeURIComponent(runId)}/score?${q}`);
125	      score = next;
126	      const parsed = parseScoreParts(next.parts);
127	      parts = parsed;
128	      if (next.part === 'lead' || next.part === 'rhythm' || next.part === 'combined') {
