133	      if (!didInitialListenSync) {
134	        listen = listenForPart(part, next.artifacts);
135	        didInitialListenSync = true;
136	      }
137	      error = null;
138	    } catch (err) {
139	      error = err instanceof Error ? err.message : 'Could not load score.';
140	    }
141	  }
