    return sorted(set(out))


def tab_measures(
    *,
    downbeats: list[float],
    tempo_bpm: float,
    beats_per_measure: int,
    end_time: float,
) -> list[dict]:
    """Measure spans in seconds: detected downbeats when there are any, else a fixed tempo."""
    tempo = tempo_bpm if tempo_bpm and tempo_bpm > 0 else 120.0
    fixed = 60.0 / tempo * max(1, beats_per_measure)
    end_time = max(end_time, fixed)
    starts: list[float] = []
    if len(downbeats) >= 2:
        gaps = sorted(b - a for a, b in zip(downbeats, downbeats[1:]) if b > a)
        length = gaps[len(gaps) // 2] if gaps else fixed
        first = downbeats[0]
        # A short lead-in folds into the first bar; a longer one becomes a pickup bar.
        starts = [0.0] if first > 0.25 * length else []
        starts.extend(db for db in downbeats if db > 0.0 or not starts)
        if starts and starts[0] > 0.0 and first <= 0.25 * length:
            starts[0] = 0.0
        while starts[-1] + length < end_time:
            starts.append(starts[-1] + length)
        ends = [*starts[1:], starts[-1] + length]
    else:
        count = max(1, math.ceil(end_time / fixed - 1e-9))
        starts = [i * fixed for i in range(count)]
        ends = [s + fixed for s in starts]
    return [
        {"index": i, "start": round(s, 4), "end": round(e, 4)}
        for i, (s, e) in enumerate(zip(starts, ends))
        if e > s
    ]


