    this.data = data;
    const flat: FlatNote[] = [];
    for (const track of data?.tracks ?? []) {
      for (const event of track.events) {
        for (const note of event.notes) {
          flat.push({
            track: track.id,
            start: event.start,
            end: Math.max(note.end, event.start + 0.08),
            pitch: note.pitch,
            chord: event.notes.length,
          });
        }
      }
