1	<script lang="ts">
2	  import { untrack } from 'svelte';
3	
4	  import { apiFetch, apiUpload, ApiError } from '../api';
5	  import { buildRequest, type ConvertRequest, type EntryDraft } from '../convertFlow';
6	  import {
7	    defaultGuitarEngine,
8	    engineForPreset,
9	    type EntryPreset,
10	  } from '../entryDefaults';
11	
12	  type Caps = {
13	    ffmpeg: boolean;
14	    demucs: boolean;
15	    roformer: boolean;
16	    guitar_ft: boolean;
17	    lead_rhythm?: boolean;
18	    max_upload_mb: number;
19	  };
20	
21	  type YtHit = {
22	    video_id: string;
23	    title: string;
24	    channel: string;
25	    duration_sec: number | null;
26	    duration_label: string;
27	    url: string;
28	    thumbnail_url: string;
29	  };
30	
31	  let {
32	    draft = $bindable(),
33	    onconvert,
34	  }: {
35	    draft: EntryDraft;
36	    onconvert: (request: ConvertRequest, caps: Caps | null) => Promise<void>;
37	  } = $props();
38	
39	  // Seed local state once from the App-owned draft (Back from the picker restores it).
40	  const initial = untrack(() => ({ ...draft }));
41	
42	  let sourceTab = $state<'upload' | 'youtube' | 'url'>(initial.sourceTab);
43	  let title = $state(initial.title);
44	  let tuning = $state(initial.tuning);
45	  let capo = $state(initial.capo);
46	  let preset = $state<EntryPreset>(initial.preset);
47	  let fingering = $state(initial.fingering);
48	  let showAdvanced = $state(initial.showAdvanced);
49	  let saferLength = $state(initial.saferLength);
50	  let maxDuration = $state(initial.maxDuration);
51	  let fullTrackConfirm = $state(initial.fullTrackConfirm);
52	  let separateStems = $state(initial.separateStems);
53	  let guitarEngine = $state(initial.restored ? initial.guitarEngine : defaultGuitarEngine(null));
54	  let mixAware = $state(initial.mixAware);
55	  let vocalDebleed = $state(initial.vocalDebleed);
56	  let onset = $state(initial.onset);
57	  let frame = $state(initial.frame);
58	  let tempoOverride = $state(initial.tempoOverride);
59	
60	  let uploadId = $state<string | null>(initial.uploadId);
61	  let uploadName = $state(initial.uploadName);
62	  let uploadDuration = $state(initial.uploadDuration);
63	  let youtubeUrl = $state(initial.youtubeUrl);
64	  let youtubeTitle = $state(initial.youtubeTitle);
65	  let mediaUrl = $state(initial.mediaUrl);
66	
67	  let caps = $state<Caps | null>(null);
68	  let busy = $state(false);
69	  let error = $state<string | null>(null);
70	  let dragOver = $state(false);
71	  let fileInput: HTMLInputElement | undefined = $state();
72	
73	  let ytOpen = $state(false);
74	  let ytQuery = $state('');
75	  let ytHits = $state<YtHit[]>([]);
76	  let ytPage = $state(1);
77	  let ytError = $state<string | null>(null);
78	  let ytBusy = $state(false);
79	
80	  let summary = $derived.by(() => {
81	    const length = saferLength ? `First ${maxDuration} s` : 'Full track';
82	    const stems = separateStems ? 'stem separation on' : 'no stem separation';
83	    return `${length} · ${stems}`;
84	  });
85	
86	  let canConvert = $derived.by(() => {
87	    if (busy) return false;
88	    if (caps && !caps.ffmpeg) return false;
89	    if (sourceTab === 'upload') return Boolean(uploadId);
90	    if (sourceTab === 'youtube') return Boolean(youtubeUrl.trim());
91	    return Boolean(mediaUrl.trim());
92	  });
93	
94	  function syncDraft() {
95	    Object.assign(draft, {
96	      restored: true,
97	      sourceTab,
98	      title,
99	      tuning,
100	      capo,
101	      preset,
102	      fingering,
103	      showAdvanced,
104	      saferLength,
105	      maxDuration,
106	      fullTrackConfirm,
107	      separateStems,
108	      guitarEngine,
109	      mixAware,
110	      vocalDebleed,
111	      onset,
112	      frame,
113	      tempoOverride,
114	      uploadId,
115	      uploadName,
116	      uploadDuration,
117	      youtubeUrl,
118	      youtubeTitle,
119	      mediaUrl,
120	    });
121	  }
122	
123	  $effect(syncDraft);
124	
125	  $effect(() => {
126	    void apiFetch<Caps>('/api/capabilities')
127	      .then((c) => {
128	        caps = c;
129	      })
130	      .catch(() => {
131	        caps = {
132	          ffmpeg: true,
133	          demucs: false,
134	          roformer: false,
135	          guitar_ft: false,
136	          lead_rhythm: false,
137	          max_upload_mb: 200,
138	        };
139	      });
140	  });
141	
142	  // Preset drives the separation toggles; caps can upgrade the default engine.
143	  // A restored draft keeps the user's own choices until they change the preset.
144	  let lastPreset: EntryPreset | null = initial.restored ? initial.preset : null;
145	  let lastCaps: Caps | null = null;
146	  $effect(() => {
147	    const p = preset;
148	    const c = caps;
149	    const presetChanged = p !== lastPreset;
150	    const capsArrived = c !== lastCaps;
151	    lastCaps = c;
152	    if (presetChanged) {
153	      separateStems = p === 'full_mix';
154	      mixAware = p === 'full_mix';
155	      lastPreset = p;
156	    }
157	    if (capsArrived && c && !initial.restored) {
158	      // First capability load on a fresh draft: capability-aware default engine.
159	      guitarEngine = engineForPreset(p, defaultGuitarEngine(c), c);
160	    } else if (presetChanged) {
161	      guitarEngine = engineForPreset(p, untrack(() => guitarEngine), c);
162	    }
163	  });
164	
165	  async function uploadFile(file: File) {
166	    busy = true;
167	    error = null;
168	    try {
169	      const res = await apiUpload(file);
170	      uploadId = res.upload_id;
171	      uploadName = res.name;
172	      uploadDuration = res.duration_sec;
173	      if (!title.trim()) title = res.name.replace(/\.[^.]+$/, '');
174	      sourceTab = 'upload';
175	    } catch (err) {
176	      error = err instanceof Error ? err.message : 'Upload failed.';
177	    } finally {
178	      busy = false;
179	    }
180	  }
181	
182	  async function onFile(ev: Event) {
183	    const input = ev.currentTarget as HTMLInputElement;
184	    const file = input.files?.[0];
185	    if (!file) return;
186	    await uploadFile(file);
187	  }
188	
189	  function onDrop(ev: DragEvent) {
190	    ev.preventDefault();
191	    dragOver = false;
192	    const file = ev.dataTransfer?.files?.[0];
193	    if (file) void uploadFile(file);
194	  }
195	
196	  async function searchYt() {
197	    ytBusy = true;
198	    ytError = null;
199	    try {
200	      const res = await apiFetch<{ page: number; hits: YtHit[] }>('/api/youtube/search', {
201	        method: 'POST',
202	        headers: { 'Content-Type': 'application/json' },
203	        body: JSON.stringify({ query: ytQuery, page: ytPage }),
204	      });
205	      ytHits = res.hits;
206	    } catch (err) {
207	      ytError = err instanceof ApiError ? err.message : 'Search failed.';
208	      ytHits = [];
209	    } finally {
210	      ytBusy = false;
211	    }
212	  }
213	
214	  function pickYt(hit: YtHit) {
215	    youtubeUrl = hit.url;
216	    youtubeTitle = hit.title;
217	    if (!title.trim()) title = hit.title;
218	    sourceTab = 'youtube';
219	    ytOpen = false;
220	  }
221	
222	  function clearUpload() {
223	    uploadId = null;
224	    uploadName = '';
225	    uploadDuration = 0;
226	    if (fileInput) fileInput.value = '';
227	  }
228	
229	  async function convert() {
230	    error = null;
231	    if (caps && !caps.ffmpeg) {
232	      error = 'ffmpeg is required. Install it and restart.';
233	      return;
234	    }
235	    syncDraft();
236	    const request = buildRequest(draft);
237	    if ('error' in request) {
238	      error = request.error;
239	      return;
240	    }
241	    busy = true;
242	    try {
243	      await onconvert(request, caps);
244	    } catch (err) {
245	      error = err instanceof Error ? err.message : 'Could not start conversion.';
246	    } finally {
247	      busy = false;
248	    }
249	  }
250	</script>
