  if (count <= 0) return 'Choose a part';
  return `Tab ${count} ${count === 1 ? 'part' : 'parts'}`;
}''', '''export function startLabel(count: number): string {
  if (count <= 0) return 'Choose an instrument';
  return `Make ${count} ${count === 1 ? 'tab' : 'tabs'}`;
}''')
